package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException;
import java.sql.Array; import java.util.*;
import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JdbcAdminModerationService implements AdminModerationService {
 private final JdbcTemplate jdbc; public JdbcAdminModerationService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override public List<Map<String,Object>> reports(){return jdbc.query("""
 SELECT l.id::text AS letter_id,l.bridge_id,l.status AS letter_status,l.body,l.display_nickname,count(r.id)::int AS report_count,array_agg(DISTINCT r.reason_code) AS reason_codes,min(r.created_at) AS first_reported_at
 FROM letters l JOIN reports r ON r.letter_id=l.id AND r.round=l.report_round AND r.status='pending' WHERE l.status<>'deleted' GROUP BY l.id,l.bridge_id,l.status,l.body,l.display_nickname ORDER BY min(r.created_at) ASC LIMIT 100
 """,(rs,i)->{Map<String,Object> item=new LinkedHashMap<>();item.put("letterId",rs.getString("letter_id"));item.put("bridgeId",rs.getString("bridge_id"));item.put("letterStatus",rs.getString("letter_status"));item.put("body",rs.getString("body"));item.put("displayNickname",rs.getString("display_nickname"));item.put("reportCount",rs.getInt("report_count"));Array reasons=rs.getArray("reason_codes");item.put("reasonCodes",reasons==null?List.of():Arrays.asList((String[])reasons.getArray()));item.put("firstReportedAt",rs.getTimestamp("first_reported_at").toInstant().toString());return item;});}
 @Transactional @Override public Map<String,Object> review(String id,String decision,String reason,String actorId){
  if(!Set.of("hide","keep_hidden","restore","dismiss","delete").contains(decision))throw bad("INVALID_DECISION","처리 방법을 확인해 주세요.");if(reason==null||reason.trim().length()<2||reason.length()>500)throw bad("INVALID_REASON","처리 사유를 입력해 주세요.");
  var letters=jdbc.query("select status,report_round from letters where id=?::uuid for update",(rs,i)->new Object[]{rs.getString(1),rs.getInt(2)},id);if(letters.isEmpty()||"deleted".equals(letters.get(0)[0]))throw new ApiException(HttpStatus.NOT_FOUND,"LETTER_NOT_FOUND","편지를 찾을 수 없습니다.");String status=(String)letters.get(0)[0];int round=(Integer)letters.get(0)[1];
  if("hide".equals(decision)&&!"published".equals(status))throw state();if("keep_hidden".equals(decision)&&!"hidden".equals(status))throw state();if("restore".equals(decision)&&!"hidden".equals(status))throw state();if("dismiss".equals(decision)&&!"published".equals(status))throw state();
  String result;if("delete".equals(decision)){int reactions=jdbc.update("delete from reactions where letter_id=?::uuid",id);int saves=jdbc.update("delete from saves where letter_id=?::uuid",id);jdbc.update("update letters set status='deleted',body=null,display_nickname=null,author_user_id=null,deleted_at=now() where id=?::uuid",id);jdbc.update("update reports set status='upheld' where letter_id=?::uuid and status='pending'",id);jdbc.update("insert into deletion_events (id,letter_id,actor_user_id,reason,reaction_count,save_count) values (?::uuid,?::uuid,?::uuid,?,?,?)",UUID.randomUUID().toString(),id,actorId,reason.trim(),reactions,saves);result="deleted";}else if("hide".equals(decision)){jdbc.update("update letters set status='hidden',hidden_at=now() where id=?::uuid",id);result="hidden";}else if("keep_hidden".equals(decision)){jdbc.update("update reports set status='upheld' where letter_id=?::uuid and round=? and status='pending'",id,round);result="hidden";}else{jdbc.update("update reports set status='dismissed' where letter_id=?::uuid and round=? and status='pending'",id,round);jdbc.update("update letters set status='published',hidden_at=null,report_round=report_round+1 where id=?::uuid",id);result="published";}
  jdbc.update("insert into admin_actions (id,actor_user_id,action,target_id,reason) values (?::uuid,?::uuid,?,?,?)",UUID.randomUUID().toString(),actorId,"letter."+decision,id,reason.trim());return Map.of("id",id,"status",result);
 }
 private ApiException bad(String c,String m){return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,c,m);}private ApiException state(){return new ApiException(HttpStatus.CONFLICT,"INVALID_STATE","현재 상태에서 처리할 수 없습니다.");}
}
